typedef enum xhttpbodypiecekind {
	XHTTP_BODY_PIECE_BYTES = 1,
	XHTTP_BODY_PIECE_BODY = 2
} xhttpbodypiecekind;



/* 未被 Kind 选中的字段必须保持为空，避免无意保留无效对象。 */
typedef struct xhttpbodypiece {
	xhttpbodypiecekind Kind;
	xbytesview Bytes;
	xhttpbody* Body;
} xhttpbodypiece;

